// Plan a scheduler run over this repo's real tasks with every precondition answering "go",
// and print which canon-curation tasks the run would ask/file.
import { readFileSync } from 'node:fs';
const root = process.argv[2];
const { discoverTasks } = await import(`${root}/packs/claudinite-tasks/src/contract/discover.mjs`);
const { planSchedulerRun } = await import(`${root}/packs/claudinite-tasks/src/schedule/run.mjs`);
const config = JSON.parse(readFileSync(`${root}/.claudinite-settings.json`, 'utf8'));
const { tasks, errors } = await discoverTasks(root, config);
if (errors.length) console.log('discover errors:', errors);
const { asked } = await planSchedulerRun({
  tasks, now: new Date().toISOString(), schedule: config.taskScheduler,
  evaluate: async () => ({ run: true }),
});
console.log('tasks discovered:', tasks.length, 'asked:', asked.length);
for (const t of tasks.filter((t) => t.pack === 'claudinite-canon-curation')) {
  const key = `${t.pack}/${t.id}`;
  console.log(asked.some((a) => a.task === key) ? 'ASKED   ' : 'skipped ', key);
}

